import fs from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"
import Ajv2020 from "ajv/dist/2020.js"
import standaloneCode from "ajv/dist/standalone/index.js"
import { compile } from "json-schema-to-typescript"

const webDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..")
const schemaPath = path.resolve(webDir, "../spec/schema/observespec.v0.json")
const outDir = path.join(webDir, "src/spec")
const banner =
  "/* Generated by web/scripts/gen-spec.mjs from spec/schema/observespec.v0.json. Do not edit; run make generate. */"

const schema = JSON.parse(fs.readFileSync(schemaPath, "utf8"))

const types = await compile(schema, "Dashboard", {
  bannerComment: banner,
  additionalProperties: false,
  ignoreMinAndMaxItems: true,
})

const ajv = new Ajv2020({
  code: { source: true, esm: true },
  allErrors: true,
  strict: true,
  discriminator: true,
})
ajv.addSchema(schema)
let code = standaloneCode(ajv, {
  validate: schema.$id,
  dataPanel: `${schema.$id}#/$defs/dataPanel`,
  textPanel: `${schema.$id}#/$defs/textPanel`,
  placeholderPanel: `${schema.$id}#/$defs/placeholderPanel`,
  rowPanel: `${schema.$id}#/$defs/rowPanel`,
})
code = code.replace(
  /const (\w+) = require\("ajv\/dist\/runtime\/ucs2length"\)\.default;/g,
  "const $1 = (s) => Array.from(s).length;"
)
code = code.replace(
  /const (\w+) = require\("ajv\/dist\/runtime\/equal"\)\.default;/g,
  (_, name) => `const ${name} = (a, b) => {
  if (a === b) return true
  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null) return false
  if (Array.isArray(a) !== Array.isArray(b)) return false
  if (Array.isArray(a)) return a.length === b.length && a.every((v, i) => ${name}(v, b[i]))
  const ka = Object.keys(a)
  return ka.length === Object.keys(b).length && ka.every((k) => Object.prototype.hasOwnProperty.call(b, k) && ${name}(a[k], b[k]))
};`
)
if (
  /\brequire\(|\bimport\s*\(|^\s*import\s|^\s*export\s[^\n]*\sfrom\s/m.test(
    code
  )
) {
  throw new Error(
    "standalone validator still imports a runtime module; extend the inlining in gen-spec.mjs"
  )
}
const validator = `${banner}\n// @ts-nocheck\n${code}\n`

const outputs = { "observespec.gen.ts": types, "validate.gen.ts": validator }
const check = process.argv.includes("--check")
const stale = []
if (check && fs.existsSync(outDir)) {
  for (const name of fs.readdirSync(outDir)) {
    if (name.endsWith(".gen.ts") && !(name in outputs)) stale.push(name)
  }
}
for (const [name, content] of Object.entries(outputs)) {
  const file = path.join(outDir, name)
  if (check) {
    if (!fs.existsSync(file) || fs.readFileSync(file, "utf8") !== content) {
      stale.push(name)
    }
  } else {
    fs.mkdirSync(outDir, { recursive: true })
    fs.writeFileSync(file, content)
  }
}
if (stale.length > 0) {
  console.error(
    `web/src/spec is stale (${stale.join(", ")}); run make generate`
  )
  process.exit(1)
}
